struct Buffer {
    private(set) var storage: [UInt8] = []
    mutating func assign(_ source: [UInt8]) {
        var next = source                 // build the complete new value first
        next.reserveCapacity(source.count) // all growth work happens off to the side
        swap(&storage, &next)             // commit: stdlib swap, cannot fail
    }                                     // 'next' now holds the old storage and is released
}
var a = Buffer(); var b = a               // assignment copies: no shared mutable state
